function LONGEST_SMOOTH_CHAIN(sigma):
    if not IS_SMOOTH(sigma): return -1
    best <- 0
    for each tau that sigma covers (len(tau) = len(sigma)-1):
        sub <- LONGEST_SMOOTH_CHAIN(tau)
        if sub >= 0: best <- max(best, 1 + sub)
    return best

